public int trap(int[] height) {
    java.util.Deque<Integer> stack = new java.util.ArrayDeque<>();
    int water = 0;
    for (int i = 0; i < height.length; i++) {
        while (!stack.isEmpty() && height[i] > height[stack.peek()]) {
            int bottom = stack.pop();
            if (stack.isEmpty()) break;
            int left = stack.peek();
            int width = i - left - 1;
            int boundedHeight = Math.min(height[left], height[i]) - height[bottom];
            water += width * boundedHeight;
        }
        stack.push(i);
    }
    return water;
}

public int trap(int[] height) {
    int l = 0, r = height.length - 1;
    int leftMax = 0, rightMax = 0, water = 0;
    while (l < r) {
        if (height[l] < height[r]) {
            leftMax = Math.max(leftMax, height[l]);
            water += leftMax - height[l];
            l++;
        } else {
            rightMax = Math.max(rightMax, height[r]);
            water += rightMax - height[r];
            r--;
        }
    }
    return water;
}

public int sumSubarrayMins(int[] arr) {
    final int MOD = 1_000_000_007;
    int n = arr.length;
    long sum = 0;
    java.util.Deque<Integer> stack = new java.util.ArrayDeque<>();
    for (int i = 0; i <= n; i++) {
        int cur = (i == n) ? Integer.MIN_VALUE : arr[i];
        while (!stack.isEmpty() && arr[stack.peek()] > cur) {
            int mid = stack.pop();
            int left = stack.isEmpty() ? -1 : stack.peek();
            long count = (long) (mid - left) * (i - mid);
            sum = (sum + count % MOD * arr[mid]) % MOD;
        }
        stack.push(i);
    }
    return (int) sum;
}

public String removeKdigits(String num, int k) {
    java.util.Deque<Character> stack = new java.util.ArrayDeque<>();
    for (char c : num.toCharArray()) {
        while (!stack.isEmpty() && k > 0 && stack.peek() > c) {
            stack.pop();
            k--;
        }
        stack.push(c);
    }
    while (k-- > 0) stack.pop();
    StringBuilder sb = new StringBuilder();
    java.util.Iterator<Character> it = stack.descendingIterator();
    while (it.hasNext()) sb.append(it.next());
    int i = 0;
    while (i < sb.length() && sb.charAt(i) == '0') i++;
    String res = sb.substring(i);
    return res.isEmpty() ? "0" : res;
}

public String removeDuplicateLetters(String s) {
    int[] lastIndex = new int[26];
    for (int i = 0; i < s.length(); i++) lastIndex[s.charAt(i) - 'a'] = i;
    boolean[] inStack = new boolean[26];
    java.util.Deque<Integer> stack = new java.util.ArrayDeque<>();
    for (int i = 0; i < s.length(); i++) {
        int c = s.charAt(i) - 'a';
        if (inStack[c]) continue;
        while (!stack.isEmpty() && stack.peek() > c && lastIndex[stack.peek()] > i) {
            inStack[stack.pop()] = false;
        }
        stack.push(c);
        inStack[c] = true;
    }
    StringBuilder sb = new StringBuilder();
    java.util.Iterator<Integer> it = stack.descendingIterator();
    while (it.hasNext()) sb.append((char) ('a' + it.next()));
    return sb.toString();
}

public boolean find132pattern(int[] nums) {
    int n = nums.length;
    java.util.Deque<Integer> stack = new java.util.ArrayDeque<>();
    int third = Integer.MIN_VALUE;
    for (int i = n - 1; i >= 0; i--) {
        if (nums[i] < third) return true;
        while (!stack.isEmpty() && stack.peek() < nums[i]) {
            third = stack.pop();
        }
        stack.push(nums[i]);
    }
    return false;
}

public int maxWidthRamp(int[] nums) {
    int n = nums.length;
    java.util.Deque<Integer> stack = new java.util.ArrayDeque<>();
    for (int i = 0; i < n; i++) {
        if (stack.isEmpty() || nums[stack.peek()] > nums[i]) stack.push(i);
    }
    int max = 0;
    for (int j = n - 1; j >= 0; j--) {
        while (!stack.isEmpty() && nums[stack.peek()] <= nums[j]) {
            max = Math.max(max, j - stack.pop());
        }
    }
    return max;
}

public int[] canSeePersonsCount(int[] heights) {
    int n = heights.length;
    int[] ans = new int[n];
    java.util.Deque<Integer> stack = new java.util.ArrayDeque<>();
    for (int i = n - 1; i >= 0; i--) {
        int count = 0;
        while (!stack.isEmpty() && stack.peek() < heights[i]) {
            stack.pop();
            count++;
        }
        if (!stack.isEmpty()) count++;
        ans[i] = count;
        stack.push(heights[i]);
    }
    return ans;
}

class StockSpanner {
    private java.util.Deque<int[]> stack;

    public StockSpanner() {
        stack = new java.util.ArrayDeque<>();
    }

    public int next(int price) {
        int span = 1;
        while (!stack.isEmpty() && stack.peek()[0] <= price) {
            span += stack.pop()[1];
        }
        stack.push(new int[]{price, span});
        return span;
    }
}

public long subArrayRanges(int[] nums) {
    return sumOfExtreme(nums, true) - sumOfExtreme(nums, false);
}

// max = true sums subarray maxima; max = false sums subarray minima
private long sumOfExtreme(int[] nums, boolean max) {
    int n = nums.length;
    long sum = 0;
    java.util.Deque<Integer> stack = new java.util.ArrayDeque<>();
    for (int i = 0; i <= n; i++) {
        while (!stack.isEmpty() && shouldPop(nums, stack.peek(), i, max)) {
            int mid = stack.pop();
            int left = stack.isEmpty() ? -1 : stack.peek();
            sum += (long) (mid - left) * (i - mid) * nums[mid];
        }
        stack.push(i);
    }
    return sum;
}

private boolean shouldPop(int[] nums, int top, int i, boolean max) {
    if (i == nums.length) return true; // sentinel flushes the stack
    return max ? nums[top] < nums[i] : nums[top] > nums[i];
}
